//! GRIB1 centre-local parameter tables — GENERATED by `tools/gen_grib1_local_tables.py`.
//!
//! Do not edit by hand: re-run the script instead.
//!
//! WMO ON388 Table 2 (the international table, versions 1-127) fixes ids
//! 1-127; a centre redefines the whole 1-254 id space in local tables 128+.
//! This carries every ECMWF local table eccodes 2.34.1 ships. Tables
//! and entry counts: 128 (254), 129 (236), 130 (26), 131 (76), 132 (12), 133 (92), 140 (87), 150 (32), 151 (79), 160 (108), 162 (113), 170 (35), 171 (186), 172 (38), 173 (38), 174 (54), 175 (30), 180 (32), 190 (36), 200 (235), 201 (77), 210 (226), 211 (171), 213 (55), 215 (211), 220 (1), 228 (107), 230 (50), 235 (48).
//!
//! Other centres' local tables are not carried: eccodes ships some, in layouts
//! its own reader misparses, and the script explains why generating them would
//! label fields wrongly rather than not at all.
//!
//! Data from eccodes' `definitions/grib1/2.98.<version>.table` (Apache-2.0; the
//! parameter definitions are factual data from the ECMWF parameter database).

use crate::tables::ParameterEntry;

/// Look up `id` in the local table `table_version` of `centre`, the centre
/// whose tables the message reads (see `tables::lookup_parameter` for how that
/// is chosen). `None` when no such table is carried or it leaves `id` undefined.
pub(crate) fn lookup(centre: u8, table_version: u8, id: u8) -> Option<ParameterEntry> {
    match (centre, table_version) {
        (98, 128) => ecmwf_128(id),
        (98, 129) => ecmwf_129(id),
        (98, 130) => ecmwf_130(id),
        (98, 131) => ecmwf_131(id),
        (98, 132) => ecmwf_132(id),
        (98, 133) => ecmwf_133(id),
        (98, 140) => ecmwf_140(id),
        (98, 150) => ecmwf_150(id),
        (98, 151) => ecmwf_151(id),
        (98, 160) => ecmwf_160(id),
        (98, 162) => ecmwf_162(id),
        (98, 170) => ecmwf_170(id),
        (98, 171) => ecmwf_171(id),
        (98, 172) => ecmwf_172(id),
        (98, 173) => ecmwf_173(id),
        (98, 174) => ecmwf_174(id),
        (98, 175) => ecmwf_175(id),
        (98, 180) => ecmwf_180(id),
        (98, 190) => ecmwf_190(id),
        (98, 200) => ecmwf_200(id),
        (98, 201) => ecmwf_201(id),
        (98, 210) => ecmwf_210(id),
        (98, 211) => ecmwf_211(id),
        (98, 213) => ecmwf_213(id),
        (98, 215) => ecmwf_215(id),
        (98, 220) => ecmwf_220(id),
        (98, 228) => ecmwf_228(id),
        (98, 230) => ecmwf_230(id),
        (98, 235) => ecmwf_235(id),
        _ => None,
    }
}

