/// ECMWF local parameter table 220 (centre 98), from eccodes'
/// `definitions/grib1/2.98.220.table`.
fn ecmwf_220(id: u8) -> Option<ParameterEntry> {
    let (name, abbreviation, units) = match id {
        228 => (
            "Total precipitation observation count",
            "tpoc",
            "dimensionless",
        ),
        _ => return None,
    };
    Some(ParameterEntry {
        name,
        abbreviation,
        units,
    })
}

